def _audit_result_read(
    db: Session,
    user: User,
    *,
    run: Any,
    results: Sequence[ResultRead],
    expectation_types: Mapping[uuid.UUID, str | None],
) -> None:
    """Record a read of a run's results (G1 / #431, `action_class='access'`)."""
    exposed = _exposed_result_ids(results, expectation_types=expectation_types)
    audit_service.record_access(
        db,
        action="run_results.read",
        entity_type="run",
        entity_id=run.id,
        actor=user,
        exposed=bool(exposed),
        detail={
            "suite_id": str(run.suite_id),
            "result_count": len(results),
            "exposed_result_ids": exposed,
        },
    )


@router.get("/runs/{run_id}", response_model=RunDetailRead, summary="Get a run with its results")
def get_run(
    run_id: uuid.UUID,
    current_user: Annotated[User, Depends(get_current_user)],
    db: Annotated[Session, Depends(get_db)],
) -> RunDetailRead:
    run = svc.get_run(db, run_id)
    if run is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="run not found")
    # Gate on the run's suite: a caller who can't see the suite can't see its
    # runs (404 hides the run id too, matching the suite existence-hiding rule).
    suite = require_permission(db, run.suite_id, current_user.id, minimum="view")
    results = svc.list_results(db, run_id)
    checks = {c.id: c for c in db.scalars(select(Check).where(Check.suite_id == run.suite_id))}
    policy = suite.column_policy
    tags = _asset_column_tags(db, suite, run)
    # Per-RESULT check identity as of when each result was written (#1489) — not the check's
    # current state. `kind`/`engine` follow the same rule (#1880 review): `CheckVersion`
    # snapshots both so a stale result is never re-labeled by a later edit, and
    # `zero_sample_suppressed` needs the engine as of THIS result — a `dmf`-engine check never
    # had a row-level sample regardless of the privacy setting. One `check_versions` read.
    as_of = svc.historical_check_snapshots(db, results, checks)
    context = {r_id: snap.context for r_id, snap in as_of.items()}
    kind_by_result = {r_id: snap.kind for r_id, snap in as_of.items()}
    engine_by_result = {r_id: snap.engine for r_id, snap in as_of.items()}
    # Resolved once per request (#1887), not per result.
    zero_sample_mode = privacy_settings_service.zero_sample_mode(db)
    # `Run` has no `results` relationship to validate a RunDetailRead from directly, so validate
    # the run fields (as RunRead), graft the data-quality outcome (#571 — else checks_total/passed
    # stay at the 0/0 default here), and attach the separately-fetched, redaction-gated results.
    outcomes = svc.check_outcome_counts(db, [run.id])
    expectation_types = {r.id: context.get(r.id, (None, None))[1] for r in results}
    reads = [
        _result_read(
            r,
            tested_column=context.get(r.id, (None, None))[0],
            expectation_type=expectation_types[r.id],
            check_kind=kind_by_result.get(r.id),
            engine=engine_by_result.get(r.id, GX_ENGINE),
            policy=policy,
            tags=tags,
            zero_sample_mode=zero_sample_mode,
        )
        for r in results
    ]
    _audit_result_read(
        db, current_user, run=run, results=reads, expectation_types=expectation_types
    )
    return RunDetailRead(
        **run_reads(db, [run], outcomes, viewer=current_user)[0].model_dump(),
        results=reads,
    )


def _visible_run(db: Session, run_id: uuid.UUID, user: User) -> tuple[Any, Any]:
    """The run and its suite, or 404 — the same existence-hiding gate as `GET /runs/{id}`."""
    run = svc.get_run(db, run_id)
    if run is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="run not found")
    return run, require_permission(db, run.suite_id, user.id, minimum="view")


