}) {
  const stem = `${toFilenameStem(suiteName ?? 'run')}_run_${run.id.slice(0, 8)}`;
  const checkName = (id: string) => checkExportName(checks.get(id)?.name, id, checksKnown);
  const expectation = (id: string) => checks.get(id)?.expectation_type ?? '';

  const exportCsv = () => {
