          { key: 'json', label: 'Download JSON', onClick: exportJson },
          { key: 'pdf', label: 'Print / Save as PDF', onClick: exportPdf },
        ],
      }}
      disabled={run.results.length === 0}
    >
      <Button icon={<DownloadOutlined />}>Download</Button>
    </Dropdown>
  );
}

